  document.querySelectorAll('[data-revoke-user]').forEach(b=>b.onclick=async()=>{if(!await confirmAction({title:'Revoke workspace access',message:'This person will no longer be able to open this organization workspace, but their Sentinel account and access to other organizations are preserved.',confirmLabel:'Revoke access',danger:true}))return;try{await api(`/users/${b.dataset.revokeUser}/revoke`,{method:'POST'});toast('Workspace access revoked.');renderUsers()}catch(err){toast(err.message,'error')}});
