  document.querySelectorAll('[data-delete-user]').forEach(b=>b.onclick=async()=>{const u=users.find(x=>x._id===b.dataset.deleteUser);if(!await confirmAction({title:'Remove team member',message:`Remove ${u?.name||'this person'} from ${currentOrganization?.name||'this workspace'}? Their Sentinel account is preserved if they belong to another organization.`,confirmLabel:'Remove from workspace',danger:true}))return;try{await api(`/users/${b.dataset.deleteUser}`,{method:'DELETE'});toast('Member removed from workspace.');renderUsers()}catch(err){toast(err.message,'error')}});
