function statusTile(label,ok,detail,warning=false){return `<div class="readiness-item ${ok?'ok':warning?'warn':'off'}"><div class="readiness-icon">${ok?'✓':warning?'!':'×'}</div><div><strong>${esc(label)}</strong><span>${esc(detail||'')}</span></div></div>`}
function sourceBadge(env){if(env==='benchmark')return '<span class="badge benchmark">Benchmark</span>';if(env==='test')return '<span class="badge test">Test</span>';return '<span class="badge operational">Operational</span>'}
function modelScopeLabel(scope){return ({'verified-preview-fallback':'Verified offline baseline','public-20k-sample':'Public 20K baseline','user-supplied-cicids':'Organization-trained model'})[scope]||scope||'Unknown'}
function payloadEnvironment(payload){return payload?.detection?.environment||payload?.traffic?.environment||'operational'}
function isOperationalPayload(payload){return payloadEnvironment(payload)==='operational'}

function legacy_shellHtml(){return `<div class="shell"><aside class="sidebar" id="sidebar"><div class="side-brand"><div class="brand-mark"><div class="brand-glyph"><span>MS</span></div><div><strong>MABELI SENTINEL</strong><small>BY MABELI TECHNOLOGY</small></div></div></div><div class="workspace-box"><label>Organization workspace</label><select class="select workspace-select" id="workspace-select">${organizations.map(o=>`<option value="${o._id}" ${String(o._id)===String(currentOrganization?._id)?'selected':''}>${esc(o.name)} · ${esc(o.role)}</option>`).join('')}</select></div><nav class="nav"><div class="nav-section">GET STARTED</div>${navButton('onboarding','Getting started','GS')}${navButton('dashboard','Command overview','OV')}<div class="nav-section">DETECT</div>${navButton('analyze','Single analysis','SA')}${navButton('batch','Batch analysis','BA')}${navButton('live','Live operations','LO')}${navButton('detections','Detection history','DT')}<div class="nav-section">RESPOND</div>${navButton('alerts','Alerts','AL')}${navButton('incidents','Incidents','IN')}${navButton('analytics','Analytics','AN')}${navButton('reports','Reports','RP')}<div class="nav-section">ADVANCED</div>${navButton('readiness','System readiness','SR')}${navButton('benchmark','Model evaluation','ME')}${navButton('testkit','Test Centre','TC')}${navButton('model','Model intelligence','ML')}<div class="nav-section">WORKSPACE</div>${navButton('integrations','Traffic sources','TS',true)}${navButton('users','Team & access','UA',true)}${navButton('audit','Audit log','LG',true)}${navButton('settings','Detection settings','DS',true)}${navButton('help','Help & how it works','HP')}</nav><div class="sidebar-foot"><div class="user-chip"><div class="avatar">${esc((currentUser?.name||'U').slice(0,2).toUpperCase())}</div><div><strong>${esc(currentUser?.name)}</strong><span>${esc(currentUser?.role)} · ${esc(currentOrganization?.name||'')}</span></div></div><button class="btn ghost small full" id="logout">Sign out</button></div></aside><main class="main"><header class="topbar"><div class="topbar-left"><button class="btn ghost small mobile-menu" id="menu">MENU</button><div class="page-title" id="top-title"></div></div><div class="system-state" id="system-state"><span class="dot"></span>Checking protection</div></header><section class="content" id="content"></section></main></div>`}

async function bootstrapBenchmarkQuietly(){
  if(sessionStorage.getItem('sentinel_benchmark_ensure')==='done')return;
  if(benchmarkEnsurePromise)return benchmarkEnsurePromise;
  sessionStorage.setItem('sentinel_benchmark_ensure','running');
  benchmarkEnsurePromise=api('/benchmark/ensure',{method:'POST',body:JSON.stringify({})})
    .then(result=>{sessionStorage.setItem('sentinel_benchmark_ensure','done');return result})
    .catch(e=>{sessionStorage.removeItem('sentinel_benchmark_ensure');console.warn('Benchmark bootstrap deferred:',e.message)})
    .finally(()=>{benchmarkEnsurePromise=null});
  return benchmarkEnsurePromise;
}

async function switchWorkspace(id){
  const org=organizations.find(o=>String(o._id)===String(id));if(!org)return;
  currentOrganization=org;currentUser.role=org.role;localStorage.setItem('sentinel_organization',JSON.stringify(org));localStorage.setItem('sentinel_user',JSON.stringify(currentUser));
  sessionStorage.removeItem('sentinel_benchmark_ensure');if(socket){socket.disconnect();socket=null}liveItems=[];toast(`Switched to ${org.name}`);renderShell();
}

function legacy_renderShell(){
  app.innerHTML=shellHtml();
  document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route));
  document.getElementById('logout').onclick=logout;
  document.getElementById('menu').onclick=()=>document.getElementById('sidebar').classList.toggle('open');
  const ws=document.getElementById('workspace-select');if(ws)ws.onchange=()=>switchWorkspace(ws.value);
  connectSocket();checkHealth();
  bootstrapBenchmarkQuietly().then(()=>{if(currentRoute==='dashboard'||currentRoute==='readiness'||currentRoute==='benchmark')renderRoute()});
  renderRoute();
}

async function checkHealth(){
  try{
    const r=await api('/system/readiness');
    const modelReady=Boolean(r.model?.ready), allServices=r.services?.api&&r.services?.database&&r.services?.ml;
    const el=document.getElementById('system-state'); if(!el)return;
    const upgrading=r.model?.bootstrap?.state==='upgrading'||r.ml?.bootstrap?.state==='upgrading';
    if(allServices&&modelReady) el.innerHTML=`<span class="dot"></span>${upgrading?'Protection ready · strengthening model':'Protection ready'}`;
    else el.innerHTML=`<span class="dot off"></span>${allServices?'Model unavailable':'Service degraded'}`;
  }catch{const e=document.getElementById('system-state');if(e)e.innerHTML='<span class="dot off"></span>Service degraded'}
}

function connectSocket(){
  if(socket)socket.disconnect();socket=io({auth:{token,organizationId:currentOrganization?._id}});
  socket.on('detection:new',payload=>{
    const env=payloadEnvironment(payload);
    if(env==='operational'){liveItems.unshift(payload);liveItems=liveItems.slice(0,80);if(currentRoute==='live')renderLiveFeed()}
    if(currentRoute==='dashboard')renderDashboard();
    if(currentRoute==='benchmark'&&env==='benchmark')renderBenchmark();
    if(currentRoute==='testkit'&&env==='test')renderTestKit();
  });
  socket.on('alert:update',()=>{if(currentRoute==='alerts')renderAlerts();if(currentRoute==='dashboard')renderDashboard()});
}

