async function legacy_renderDashboard(){
  let readiness=await api('/system/readiness');
  if(!readiness.traffic?.benchmark){try{await bootstrapBenchmarkQuietly();readiness=await api('/system/readiness')}catch{}}
  let scope=dashboardScope;
  if(scope==='auto')scope=(readiness.traffic?.operational||0)>0?'operational':'benchmark';
  if(!['operational','test','benchmark'].includes(scope))scope='operational';
  const d=await api(`/dashboard?scope=${scope}`); const total=d.total||0,mal=d.malicious||0;
  const benchmark=scope==='benchmark', test=scope==='test';
  const context=benchmark
    ? `<div class="context-banner benchmark-context"><div><strong>CICIDS2017 Benchmark View</strong><span>Genuine benchmark-derived model decisions for validation. They are not attacks against the customer organization.</span></div><button class="btn small" id="open-benchmark">Open Benchmark Lab</button></div>`
    : test
      ? `<div class="context-banner test-context"><div><strong>Isolated Test View</strong><span>Setup-verification detections, alerts and incidents live here. Test activity is clearly separated from real organization operational records.</span></div><button class="btn small" id="open-testkit">Open Test Centre</button></div>`
      : `<div class="context-banner operational-context"><div><strong>Operational view</strong><span>Only traffic from live integrations, analyst operational analysis, or explicitly operational batches appears here.</span></div>${readiness.integrations?.connected?'<span class="badge benign">Live source connected</span>':'<button class="btn small" id="connect-source">Connect live source</button>'}</div>`;
  const alertsLabel=benchmark?'Validation scope':'Active alerts';
  const fifthLabel=benchmark?'Model version':'Critical alerts';
  const sixthLabel=benchmark?'Ground truth':'Open incidents';
  document.getElementById('content').innerHTML=`${pageHead('dashboard','<button class="btn primary" data-go="analyze">Analyze traffic</button>')}<div class="scope-tabs"><button data-scope="operational" class="${scope==='operational'?'active':''}">Operational</button><button data-scope="test" class="${scope==='test'?'active':''}">Test</button><button data-scope="benchmark" class="${scope==='benchmark'?'active':''}">Benchmark</button></div>${context}<div class="grid stats"><div class="stat"><div class="label">Traffic analyzed</div><div class="value">${total.toLocaleString()}</div></div><div class="stat"><div class="label">Benign</div><div class="value">${(d.benign||0).toLocaleString()}</div></div><div class="stat"><div class="label">Malicious</div><div class="value">${mal.toLocaleString()}</div></div><div class="stat"><div class="label">${alertsLabel}</div><div class="value">${benchmark?'CICIDS':d.activeAlerts||0}</div></div><div class="stat ${benchmark?'':'critical'}"><div class="label">${fifthLabel}</div><div class="value compact-value">${benchmark?esc((readiness.model?.version||'—').split('.').slice(-2).join('.')):d.criticalAlerts||0}</div></div><div class="stat"><div class="label">${sixthLabel}</div><div class="value">${benchmark?'✓':d.openIncidents||0}</div></div></div><div class="panel-grid" style="margin-top:16px"><div class="panel"><div class="panel-head"><h2>Recent detections</h2><span class="muted small">${benchmark?'Benchmark validation decisions':test?'Isolated test decisions':'Newest operational model decisions'}</span></div>${d.recentDetections?.length?tableDetections(d.recentDetections):empty(benchmark?'Benchmark validation is preparing':test?'No test traffic yet':'No operational traffic yet',benchmark?'Open Benchmark Lab to run genuine CICIDS2017 validation.':test?'Open Test Centre and run the full setup-verification workflow.':'Connect a live source or run an operational analysis; the system is ready and waiting for real organization traffic.')}</div><div class="stack"><div class="panel"><div class="panel-head"><h2>Attack composition</h2><span class="muted small">${benchmark?'Benchmark predictions':test?'Test malicious records':'Operational malicious records'}</span></div>${d.attacks?.length?bars(d.attacks):empty('No malicious detections','No malicious records exist in this environment yet.')}</div><div class="panel"><div class="panel-head"><h2>Detection ratio</h2></div><div class="metric-big">${total?pct(mal/total):'0%'}</div><p class="muted small">Malicious share of ${scope} detections.</p></div></div></div>`;
  document.querySelector('[data-go="analyze"]')?.addEventListener('click',()=>go('analyze'));
  document.querySelectorAll('[data-scope]').forEach(x=>x.onclick=()=>{dashboardScope=x.dataset.scope;localStorage.setItem('sentinel_dashboard_scope',dashboardScope);renderDashboard()});
  document.getElementById('open-benchmark')?.addEventListener('click',()=>go('benchmark'));
  document.getElementById('open-testkit')?.addEventListener('click',()=>go('testkit'));
  document.getElementById('connect-source')?.addEventListener('click',()=>go('integrations'));
  wireDetectionRows();wireCopyButtons(document.getElementById('content'));
}

function tableDetections(items){return `<div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>Environment</th><th>Prediction</th><th>Attack type</th><th>${items.some(r=>r.environment==='benchmark')?'Ground truth':'Confidence'}</th><th>Risk</th><th>Severity</th><th class="actions-col">Actions</th></tr></thead><tbody>${items.map(r=>`<tr data-detection="${r._id}"><td>${esc(fmtDate(r.createdAt))}</td><td>${sourceBadge(r.environment)}</td><td>${predBadge(r.prediction)}</td><td>${esc(r.attackType)}</td><td>${r.environment==='benchmark'?`${esc(r.groundTruth||'—')} ${r.isCorrect===true?'✓':r.isCorrect===false?'×':''}`:pct(r.confidence)}</td><td>${r.riskScore}/100</td><td>${severityBadge(r.severity)}</td><td><div class="row-actions"><button class="btn ghost small" data-view-detection="${r._id}">View</button>${copyButton(r._id,'Copy ID')}${currentUser?.role==='admin'?`<button class="btn danger small" data-delete-detection="${r._id}">Delete</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`}

async function openDetection(id){
  const d=await api(`/detections/${id}`); const explanations=(d.explanation||[]).map(x=>`<div class="explain-row"><header><strong>${esc(x.feature)}</strong><span>${pct(x.contribution)}</span></header><div class="muted small mono">Observed value: ${esc(x.value)}</div></div>`).join('');
  const truth=d.environment==='benchmark'||d.environment==='test'?`<div class="kv"><span>Ground truth</span><strong>${esc(d.groundTruth||'—')}</strong></div><div class="kv"><span>Class match</span><strong>${d.isCorrect===true?'Correct ✓':d.isCorrect===false?'Different prediction ×':'—'}</strong></div>`:'';
  const featureJson=JSON.stringify(d.trafficEvent?.features||{},null,2);const evidenceJson=JSON.stringify(d,null,2);
  drawer(`<div class="eyebrow">Detection evidence</div><div class="drawer-title-row"><h2>${esc(d.attackType)}</h2><div class="row-actions">${copyButton(d._id,'Copy ID')}${copyButton(evidenceJson,'Copy evidence JSON')}</div></div>${sourceBadge(d.environment)} ${predBadge(d.prediction)} ${severityBadge(d.severity)}<div style="margin-top:18px"><div class="kv"><span>Confidence</span><strong>${pct(d.confidence)}</strong></div><div class="kv"><span>Malicious probability</span><strong>${pct(d.maliciousProbability)}</strong></div><div class="kv"><span>Risk score</span><strong>${d.riskScore}/100</strong></div>${truth}<div class="kv"><span>Model</span><strong>${esc(d.modelAlgorithm||'—')} ${esc(d.modelVersion||'')}</strong></div><div class="kv"><span>Source</span><strong>${esc(d.trafficEvent?.sourceName||'—')}</strong></div><div class="kv"><span>Source IP</span><strong class="mono">${esc(d.trafficEvent?.sourceIp||'—')}</strong></div><div class="kv"><span>Destination IP</span><strong class="mono">${esc(d.trafficEvent?.destinationIp||'—')}</strong></div><div class="kv"><span>Observed</span><strong>${esc(fmtDate(d.createdAt))}</strong></div></div><h3 style="margin-top:22px">Model explanation</h3><div class="explain" style="margin-top:10px">${explanations||'<div class="muted small">No feature-importance explanation is available for this model.</div>'}</div><div class="drawer-title-row" style="margin-top:22px"><h3>Captured traffic features</h3>${copyButton(featureJson,'Copy features')}</div><pre class="notice mono code-scroll">${esc(featureJson)}</pre>${canAdmin()?'<div class="drawer-actions"><button class="btn danger" id="delete-detection-drawer">Delete detection</button></div>':''}`);
  wireCopyButtons(document.querySelector('.drawer'));
  document.getElementById('delete-detection-drawer')?.addEventListener('click',async()=>{if(!await confirmAction({title:'Delete detection',message:'This deletes the detection, captured traffic event, and any alert directly linked to it.',confirmLabel:'Delete detection',danger:true}))return;try{await api(`/detections/${id}`,{method:'DELETE'});document.getElementById('drawer-close')?.click();toast('Detection deleted.');currentRoute==='detections'?renderDetections():renderDashboard()}catch(err){toast(err.message,'error')}});
}

async function renderLive(){
  const d=await api('/detections?environment=operational&limit=30');liveItems=d.items.map(x=>({detection:x,traffic:x.trafficEvent}));
  const r=await api('/system/readiness').catch(()=>null);
  document.getElementById('content').innerHTML=`${pageHead('live')}<div class="context-banner operational-context"><div><strong>Operational stream only</strong><span>Benchmark validation records never appear in this feed and never create operational alerts.</span></div>${r?.integrations?.connected?'<span class="badge benign">Collector heartbeat received</span>':'<span class="badge medium">Awaiting live collector</span>'}</div><div class="panel"><div class="panel-head"><h2>Streaming detection feed</h2><div class="system-state"><span class="pulse"></span>Socket connected</div></div><div class="notice" style="margin-bottom:14px">Entries here come from authenticated live integrations, analyst single-flow analysis, or unlabelled operational batches. Mabeli Sentinel never converts benchmark attacks into customer organization incidents.</div><div id="live-feed" class="live-feed"></div></div>`;renderLiveFeed()
}

async function renderBenchmark(){
  let b=await api('/benchmark');
  if(!b.total){await bootstrapBenchmarkQuietly();b=await api('/benchmark')}
  const latest=b.lastRuns?.[0]; const info=b.info||{},m=b.model||{};
  const benchmarkActions=`<button class="btn primary" id="run-benchmark">Run 100-record validation</button>${canAdmin()?'<button class="btn danger" id="clear-benchmark">Clear benchmark history</button>':''}`;
  document.getElementById('content').innerHTML=`${pageHead('benchmark',benchmarkActions)}<div class="context-banner benchmark-context"><div><strong>Genuine benchmark environment</strong><span>Records originate from CICIDS2017-derived public data. Results validate the detection pipeline and are explicitly isolated from Mabeli Technology operational telemetry.</span></div><span class="badge benchmark">No operational alerts</span></div><div class="grid stats benchmark-stats"><div class="stat"><div class="label">Benchmark detections</div><div class="value">${Number(b.total||0).toLocaleString()}</div></div><div class="stat"><div class="label">Malicious predicted</div><div class="value">${Number(b.malicious||0).toLocaleString()}</div></div><div class="stat"><div class="label">Binary accuracy</div><div class="value">${b.total?pct((b.binaryCorrect||0)/b.total):'—'}</div></div><div class="stat"><div class="label">Exact class match</div><div class="value">${b.total?pct((b.correct||0)/b.total):'—'}</div></div><div class="stat"><div class="label">Source records</div><div class="value">${Number(info.records||0).toLocaleString()}</div></div><div class="stat"><div class="label">Source classes</div><div class="value">${info.classes?.length||0}</div></div></div><div class="panel-grid" style="margin-top:16px"><div class="stack"><div class="panel"><div class="panel-head"><h2>Benchmark provenance</h2>${info.fallback?'<span class="badge medium">Offline continuity subset</span>':'<span class="badge benign">Public 20K sample</span>'}</div><div class="metric-pair"><span>Dataset</span><strong>${esc(info.source_name||'CICIDS2017')}</strong></div><div class="metric-pair"><span>Available records</span><strong>${Number(info.records||0).toLocaleString()}</strong></div><div class="metric-pair"><span>Classes</span><strong>${esc((info.classes||[]).join(', '))}</strong></div><div class="metric-pair"><span>Active model</span><strong>${esc(modelScopeLabel(m.training_scope))}</strong></div><div class="quick-actions" style="margin-top:12px">${info.source_url?copyButton(info.source_url,'Copy source URL'):''}</div>${info.fallback?'<div class="notice warning" style="margin-top:12px">The bundled verified public preview keeps the system genuinely functional offline. When internet access is available, Mabeli Sentinel automatically attempts to upgrade to the 20,000-row public baseline. Use the full official CICIDS2017 dataset for your final research-grade evaluation.</div>':'<div class="notice" style="margin-top:12px">The stronger 20,000-row public CICIDS2017-derived baseline is available and is used for benchmark sampling.</div>'}</div><div class="panel"><div class="panel-head"><h2>Attack composition</h2></div>${b.attacks?.length?bars(b.attacks):empty('No benchmark attacks processed','Run benchmark validation to populate model decisions.')}</div></div><div class="panel"><div class="panel-head"><h2>Validation runs</h2><span class="muted small">Real Node → ML → MongoDB pipeline</span></div>${b.lastRuns?.length?`<div class="run-list">${b.lastRuns.map(r=>`<div class="run-card"><div><strong>${Number(r.recordsProcessed||0).toLocaleString()} records</strong><span>${fmtDate(r.completedAt||r.createdAt)}</span></div><div><span>Binary</span><strong>${pct(r.binaryAccuracy)}</strong></div><div><span>Exact class</span><strong>${pct(r.accuracy)}</strong></div><div>${severityBadge(r.status==='completed'?'resolved':'high')}</div></div>`).join('')}</div>`:empty('No validation run yet','Start a validation run to exercise the complete pipeline.')}${canAdmin()&&info.fallback?'<button class="btn" id="upgrade-model" style="margin-top:14px">Retry public 20K model upgrade</button>':''}</div></div>`;
  document.getElementById('run-benchmark').onclick=async e=>{const btn=e.currentTarget;btn.disabled=true;btn.textContent='Processing genuine benchmark traffic…';try{const r=await api('/benchmark/run',{method:'POST',body:JSON.stringify({limit:Math.min(100,Number(info.records||100))})});toast(`Validation complete. Binary accuracy ${pct(r.binaryAccuracy)}.`);renderBenchmark()}catch(err){toast(err.message,'error')}finally{btn.disabled=false;btn.textContent='Run 100-record validation'}};
  document.getElementById('upgrade-model')?.addEventListener('click',async e=>{const btn=e.currentTarget;btn.disabled=true;btn.textContent='Upgrade requested…';try{await api('/model/upgrade',{method:'POST',body:JSON.stringify({})});toast('Public baseline upgrade started in the ML service.');setTimeout(()=>renderBenchmark(),1500)}catch(err){toast(err.message,'error')}finally{btn.disabled=false;btn.textContent='Retry public 20K model upgrade'}});
  document.getElementById('clear-benchmark')?.addEventListener('click',async()=>{if(!await confirmAction({title:'Clear benchmark history',message:'Delete stored Benchmark detections, traffic events and validation-run history? The bundled benchmark fixture files and model are kept.',confirmLabel:'Clear benchmark history',danger:true}))return;try{await api('/benchmark/data',{method:'DELETE'});sessionStorage.setItem('sentinel_benchmark_ensure','done');toast('Benchmark history cleared.');renderBenchmark()}catch(err){toast(err.message,'error')}});
  wireCopyButtons(document.getElementById('content'));
}

async function renderTestKit(){
  const t=await api('/test-kit');
  const c=t.counts||{};
  document.getElementById('content').innerHTML=`${pageHead('testkit','<button class="btn primary" id="run-full-test">Generate complete test workspace</button>')}<div class="context-banner test-context"><div><strong>Safe, isolated verification environment</strong><span>Every scenario uses genuine CICIDS2017-derived traffic but is stored under the Test environment. Test alerts and incidents are visibly separated from real organization operational records.</span></div><span class="badge test">TEST DATA ONLY</span></div><div class="grid stats test-stats"><div class="stat"><div class="label">Test detections</div><div class="value">${Number(c.detections||0).toLocaleString()}</div></div><div class="stat"><div class="label">Test alerts</div><div class="value">${Number(c.alerts||0).toLocaleString()}</div></div><div class="stat"><div class="label">Test incidents</div><div class="value">${Number(c.incidents||0).toLocaleString()}</div></div><div class="stat"><div class="label">Fixture records</div><div class="value">${Number(t.benchmark?.records||0).toLocaleString()}</div></div><div class="stat"><div class="label">Fixture classes</div><div class="value">${t.benchmark?.classes?.length||0}</div></div><div class="stat"><div class="label">Source</div><div class="value compact-value">CICIDS</div></div></div><div class="panel" style="margin-top:16px"><div class="panel-head"><h2>One-click security scenarios</h2><span class="muted small">Actual model inference · isolated storage</span></div><div class="scenario-grid">${(t.scenarios||[]).map(x=>`<article class="scenario-card ${x.available?'':'disabled-card'}"><div><span class="badge test">${esc(x.label)}</span><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p></div><button class="btn ${x.id==='benign'?'':'primary'}" data-test-scenario="${x.id}" ${x.available?'':'disabled'}>Run scenario</button></article>`).join('')}</div><div id="test-run-result" style="margin-top:14px"></div></div><div class="panel-grid" style="margin-top:16px"><div class="panel"><div class="panel-head"><h2>Included test files</h2><span class="muted small">Useful for Single and Batch Analysis</span></div><div class="download-list"><a class="file-link" href="/test-data/single-benign.json" download><span>single-benign.json</span><small>Single Analysis · expected benign ground truth</small></a><a class="file-link" href="/test-data/single-portscan.json" download><span>single-portscan.json</span><small>Single Analysis · PortScan ground truth</small></a><a class="file-link" href="/test-data/batch-labelled.csv" download><span>batch-labelled.csv</span><small>Batch Analysis · labelled benchmark evaluation</small></a><a class="file-link" href="/test-data/batch-unlabelled.csv" download><span>batch-unlabelled.csv</span><small>Batch Analysis · choose Test mode for isolated alert testing</small></a></div></div><div class="panel"><div class="panel-head"><h2>Open generated records</h2><span class="muted small">Jump directly to the isolated views</span></div><div class="quick-actions"><button class="btn" id="view-test-dashboard">Test dashboard</button><button class="btn" id="view-test-detections">Test detections</button><button class="btn" id="view-test-alerts">Test alerts</button><button class="btn" id="view-test-incidents">Test incidents</button></div><div class="notice" style="margin-top:14px"><strong>Complete test workspace</strong> runs one fixture per available class, stores real model predictions, attempts to create a test alert from a genuinely malicious prediction, then opens a linked test incident. It never creates an operational organization incident.</div>${canAdmin()?'<button class="btn danger" id="clear-test-data" style="margin-top:14px">Clear all test data</button>':''}</div></div><div class="panel" style="margin-top:16px"><div class="panel-head"><h2>Setup checklist for another installer</h2><span class="muted small">No guesswork required</span></div><ol class="setup-checklist"><li>Start the stack and create the first administrator.</li><li>Open System Readiness and confirm API, MongoDB, ML service, production model and benchmark source are ready.</li><li>Open Test Centre and run <strong>Generate complete test workspace</strong>.</li><li>Open Test Detections, Test Alerts and Test Incidents to verify CRUD, copy and investigation actions.</li><li>Use the included JSON/CSV fixtures in Single Analysis and Batch Analysis.</li><li>Create a Traffic Source and use its copied <span class="mono">/api/ingest/ping</span> command to verify collector authentication without creating a detection.</li><li>Only after setup verification, connect real organization traffic and use Operational views.</li></ol></div>`;
  document.querySelectorAll('[data-test-scenario]').forEach(b=>b.onclick=async()=>{const btn=b;btn.disabled=true;const original=btn.textContent;btn.textContent='Running…';try{const r=await api('/test-kit/scenario',{method:'POST',body:JSON.stringify({scenario:btn.dataset.testScenario})});document.getElementById('test-run-result').innerHTML=`<div class="notice"><strong>${esc(r.groundTruth||'Fixture')} processed.</strong><br>Model prediction: ${predBadge(r.detection.prediction)} <strong>${esc(r.detection.attackType)}</strong> · ${severityBadge(r.detection.severity)} · confidence ${pct(r.detection.confidence)}.${r.alert?`<br>Test alert created: <strong>${esc(r.alert.title)}</strong>.`:'<br>No alert was created for this prediction.'}</div>`;toast('Test scenario completed.');setTimeout(()=>renderTestKit(),900)}catch(err){toast(err.message,'error')}finally{btn.disabled=false;btn.textContent=original}});
  document.getElementById('run-full-test').onclick=async e=>{const btn=e.currentTarget;btn.disabled=true;btn.textContent='Generating isolated test workspace…';try{const r=await api('/test-kit/full',{method:'POST',body:JSON.stringify({})});const detections=(r.results||[]).filter(x=>x.detection).length;toast(`Test workspace generated: ${detections} detections${r.alert?', alert':''}${r.incident?', incident':''}.`);renderTestKit()}catch(err){toast(err.message,'error')}finally{btn.disabled=false;btn.textContent='Generate complete test workspace'}};
  document.getElementById('view-test-dashboard').onclick=()=>{dashboardScope='test';localStorage.setItem('sentinel_dashboard_scope','test');go('dashboard')};
  document.getElementById('view-test-detections').onclick=()=>{detectionEnvironment='test';go('detections')};
  document.getElementById('view-test-alerts').onclick=()=>{alertEnvironment='test';localStorage.setItem('sentinel_alert_environment','test');go('alerts')};
  document.getElementById('view-test-incidents').onclick=()=>{incidentEnvironment='test';localStorage.setItem('sentinel_incident_environment','test');go('incidents')};
  document.getElementById('clear-test-data')?.addEventListener('click',async()=>{if(!await confirmAction({title:'Clear all test data',message:'Delete every Test-environment detection, alert, incident and captured traffic event? Operational and Benchmark records are not affected.',confirmLabel:'Clear test data',danger:true}))return;try{const r=await api('/test-kit/data',{method:'DELETE'});toast(`Test data cleared: ${r.cleared?.detections||0} detections removed.`);renderTestKit()}catch(err){toast(err.message,'error')}});
}

async function legacy_renderBatch(){
  document.getElementById('content').innerHTML=`${pageHead('batch')}<div class="panel"><div class="panel-head"><h2>CSV flow processing</h2><span class="muted small">CICIDS-compatible records</span></div><div class="notice" style="margin-bottom:14px"><strong>Choose the environment deliberately.</strong> Auto keeps labelled files in Benchmark and unlabelled files in Operational. For setup verification, choose Test so generated alerts remain isolated.</div><div class="quick-actions" style="margin-bottom:14px"><a class="btn ghost small" href="/test-data/batch-labelled.csv" download>Download labelled test CSV</a><a class="btn ghost small" href="/test-data/batch-unlabelled.csv" download>Download unlabelled test CSV</a><button class="btn ghost small" id="open-test-centre">Open Test Centre</button></div><form id="batch-form"><div class="dropzone"><div class="eyebrow">Traffic dataset</div><h3>Choose a CSV file</h3><p class="muted small">Every numeric flow row is processed through the active ML model and stored in MongoDB.</p><input type="file" name="file" accept=".csv,text/csv" required></div><div class="settings-grid compact-settings" style="margin-top:14px"><div class="field"><label>Environment</label><select class="select" name="environment"><option value="">Auto — labelled Benchmark / unlabelled Operational</option><option value="test" selected>Test — isolated setup verification</option><option value="benchmark">Benchmark — validation only</option><option value="operational">Operational — real organization activity</option></select></div><div class="field"><label>Maximum rows for this run</label><input class="input" name="maxRows" type="number" min="1" max="50000" value="5000"></div></div><button class="btn primary">Start batch analysis</button></form><div id="batch-result" style="margin-top:16px"></div></div>`;
  document.getElementById('open-test-centre').onclick=()=>go('testkit');
  document.getElementById('batch-form').onsubmit=async e=>{e.preventDefault();const btn=submitButton(e.currentTarget);btn.disabled=true;btn.textContent='Processing traffic rows…';try{const data=await api('/analysis/batch',{method:'POST',body:new FormData(e.currentTarget)});const good=data.results.filter(x=>!x.error);const malicious=good.filter(x=>x.prediction==='malicious').length;const exact=good.filter(x=>x.isCorrect===true).length;const alertNote=data.environment==='benchmark'?'No alerts are created from benchmark data.':data.environment==='test'?'Any generated alerts are isolated in the Test queue.':'Operational malicious rows may create Mabeli alerts.';document.getElementById('batch-result').innerHTML=`<div class="notice"><strong>${data.processed.toLocaleString()} rows processed in the ${esc(data.environment)} environment.</strong><br>${malicious.toLocaleString()} malicious predictions, ${(good.length-malicious).toLocaleString()} benign predictions, ${(data.results.length-good.length).toLocaleString()} failures.${data.environment==='benchmark'?`<br>Exact class matches recorded: ${exact.toLocaleString()}.`:''}<br>${esc(alertNote)}</div>`;toast('Batch analysis completed.')}catch(err){toast(err.message,'error')}finally{btn.disabled=false;btn.textContent='Start batch analysis'}};
}

async function legacy_renderDetections(page=1){
  const q=new URLSearchParams({page:String(page),limit:'25'});if(detectionEnvironment)q.set('environment',detectionEnvironment);
  const d=await api(`/detections?${q}`);
  document.getElementById('content').innerHTML=`${pageHead('detections')}<div class="panel"><div class="toolbar filter-toolbar"><select class="select" id="det-env"><option value="">All environments</option><option value="operational" ${detectionEnvironment==='operational'?'selected':''}>Operational</option><option value="test" ${detectionEnvironment==='test'?'selected':''}>Test</option><option value="benchmark" ${detectionEnvironment==='benchmark'?'selected':''}>Benchmark</option></select><select class="select" id="det-pred"><option value="">All predictions</option><option value="benign">Benign</option><option value="malicious">Malicious</option></select><select class="select" id="det-sev"><option value="">All severities</option><option>low</option><option>medium</option><option>high</option><option>critical</option></select><input class="input" id="det-attack" placeholder="Attack type, e.g. PortScan"><input class="input" id="det-from" type="date" title="From date"><input class="input" id="det-to" type="date" title="To date"><button class="btn small" id="det-filter">Apply filters</button><button class="btn ghost small" id="det-reset">Reset</button></div><div id="det-table">${d.items.length?tableDetections(d.items):empty('No detections found','There are no records matching the current filters.')}</div><div class="pager"><button class="btn small" ${d.page<=1?'disabled':''} id="prev">Previous</button><span class="muted small">Page ${d.page} of ${d.pages}</span><button class="btn small" ${d.page>=d.pages?'disabled':''} id="next">Next</button></div></div>`;
  wireDetectionRows();document.getElementById('prev').onclick=()=>renderDetections(d.page-1);document.getElementById('next').onclick=()=>renderDetections(d.page+1);
  document.getElementById('det-filter').onclick=async()=>{const env=document.getElementById('det-env').value,p=document.getElementById('det-pred').value,sev=document.getElementById('det-sev').value,attack=document.getElementById('det-attack').value.trim(),from=document.getElementById('det-from').value,to=document.getElementById('det-to').value;detectionEnvironment=env;const params=new URLSearchParams({limit:'25'});if(env)params.set('environment',env);if(p)params.set('prediction',p);if(sev)params.set('severity',sev);if(attack)params.set('attackType',attack);if(from)params.set('from',from);if(to)params.set('to',`${to}T23:59:59.999Z`);const x=await api(`/detections?${params}`);document.getElementById('det-table').innerHTML=x.items.length?tableDetections(x.items):empty('No detections found','Adjust the filters and try again.');wireDetectionRows()};
  document.getElementById('det-reset').onclick=()=>{detectionEnvironment='';renderDetections(1)};
}

async function renderAnalytics(){
  const a=await api(`/analytics?days=30&scope=${analyticsScope}`);
  const context=analyticsScope==='benchmark'?'<div class="context-banner benchmark-context"><div><strong>Benchmark analytics</strong><span>Performance and attack trends from CICIDS2017 validation data, not real incidents against the customer organization.</span></div></div>':analyticsScope==='test'?'<div class="context-banner test-context"><div><strong>Test analytics</strong><span>Trends from isolated setup-verification scenarios only. They never count as real organization operational activity.</span></div><button class="btn small" id="analytics-test-centre">Open Test Centre</button></div>':'';
  document.getElementById('content').innerHTML=`${pageHead('analytics')}<div class="scope-tabs"><button data-ascope="operational" class="${analyticsScope==='operational'?'active':''}">Operational</button><button data-ascope="test" class="${analyticsScope==='test'?'active':''}">Test</button><button data-ascope="benchmark" class="${analyticsScope==='benchmark'?'active':''}">Benchmark</button><button data-ascope="all" class="${analyticsScope==='all'?'active':''}">Combined</button></div>${context}<div class="grid stats" style="grid-template-columns:repeat(4,1fr)"><div class="stat"><div class="label">Avg confidence</div><div class="value">${pct(a.confidence.avg)}</div></div><div class="stat"><div class="label">False positives</div><div class="value">${a.falsePositives}</div></div><div class="stat"><div class="label">Attack classes</div><div class="value">${a.attacks.length}</div></div><div class="stat"><div class="label">Window</div><div class="value">${a.days}d</div></div></div><div class="panel-grid" style="margin-top:16px"><div class="panel"><div class="panel-head"><h2>Attack distribution</h2></div>${a.attacks.length?bars(a.attacks):empty('No attack analytics in this view','This chart needs malicious detections in the selected environment. Use Test Centre or Benchmark Lab to populate safe validation data.')}</div><div class="panel"><div class="panel-head"><h2>Severity distribution</h2></div>${a.severity.length?bars(a.severity.map(x=>({_id:x._id,count:x.count}))):empty('No severity distribution yet','Severity is calculated after detections are stored.')}</div></div>`;
  document.querySelectorAll('[data-ascope]').forEach(x=>x.onclick=()=>{analyticsScope=x.dataset.ascope;localStorage.setItem('sentinel_analytics_scope',analyticsScope);renderAnalytics()});
  document.getElementById('analytics-test-centre')?.addEventListener('click',()=>go('testkit'));
}

async function legacy_renderReports(){
  document.getElementById('content').innerHTML=`${pageHead('reports')}<div class="settings-grid"><div class="panel"><div class="eyebrow">Executive PDF</div><h2 style="margin:8px 0">Security management report</h2><p class="muted small">Generate a truthful operational report, isolated Test report, or clearly-labelled CICIDS2017 benchmark-validation report.</p><div class="field"><label>Environment</label><select class="select" id="report-scope"><option value="operational">Operational organization traffic</option><option value="test">Isolated Test environment</option><option value="benchmark">CICIDS2017 benchmark</option><option value="all">Combined technical export</option></select></div><div class="field"><label>Reporting window</label><select class="select" id="report-days"><option value="7">7 days</option><option value="30" selected>30 days</option><option value="90">90 days</option><option value="365">365 days</option></select></div><div class="row-actions"><button class="btn primary" id="pdf-report">Download PDF</button><button class="btn ghost" id="copy-pdf-path">Copy API path</button></div></div><div class="panel"><div class="eyebrow">Analyst CSV</div><h2 style="margin:8px 0">Detection evidence export</h2><p class="muted small">Exports environment, ground truth where available, model prediction, risk, source and network endpoints.</p><div class="row-actions"><button class="btn" id="csv-report">Download CSV</button><button class="btn ghost" id="copy-csv-path">Copy API path</button></div><div class="notice" style="margin-top:14px">Exports are generated from stored records at request time. They are not static files or placeholder reports.</div></div></div>`;
  const path=ext=>{const d=document.getElementById('report-days').value,s=document.getElementById('report-scope').value;return `/api/reports/security.${ext}?days=${d}&scope=${s}`};
  const apiPath=ext=>{const d=document.getElementById('report-days').value,s=document.getElementById('report-scope').value;return `/reports/security.${ext}?days=${d}&scope=${s}`};
  document.getElementById('pdf-report').onclick=()=>downloadReport(apiPath('pdf'),'mabeli-security-report.pdf');
  document.getElementById('csv-report').onclick=()=>downloadReport(apiPath('csv'),'mabeli-detections.csv');
  document.getElementById('copy-pdf-path').onclick=()=>copyText(path('pdf'),'PDF API path copied.');
  document.getElementById('copy-csv-path').onclick=()=>copyText(path('csv'),'CSV API path copied.');
}

async function renderModel(){
  const [m,boot]=await Promise.all([api('/model').catch(()=>({ready:false})),api('/model/bootstrap').catch(()=>({}))]); const bs=m.bootstrap||boot.bootstrap||{};
  const schemaJson=JSON.stringify(m.feature_names||[],null,2);
  document.getElementById('content').innerHTML=`${pageHead('model')}<div class="model-status"><div class="panel"><div class="panel-head"><h2>Production model</h2><div class="row-actions">${m.ready?copyButton(m.version||'','Copy version'):''}${m.ready?copyButton(m.artifact_hash||'','Copy SHA-256'):''}${m.ready?copyButton(schemaJson,'Copy feature schema'):''}${m.ready?'<span class="badge benign">Active</span>':'<span class="badge critical">Unavailable</span>'}</div></div>${m.ready?`<div class="metric-pair"><span>Name</span><strong>${esc(m.name)}</strong></div><div class="metric-pair"><span>Version</span><strong class="mono">${esc(m.version)}</strong></div><div class="metric-pair"><span>Algorithm</span><strong>${esc(m.algorithm)}</strong></div><div class="metric-pair"><span>Training scope</span><strong>${esc(modelScopeLabel(m.training_scope))}</strong></div><div class="metric-pair"><span>Training records</span><strong>${Number(m.records||0).toLocaleString()}</strong></div><div class="metric-pair"><span>Features</span><strong>${m.feature_count}</strong></div><div class="metric-pair"><span>Classes</span><strong>${m.classes?.length||0}</strong></div><div class="metric-pair"><span>Macro F1</span><strong>${pct(m.metrics?.multiclass?.f1_macro)}</strong></div><div class="metric-pair"><span>Accuracy</span><strong>${pct(m.metrics?.multiclass?.accuracy)}</strong></div><div class="metric-pair"><span>Artifact SHA-256</span><strong class="mono truncate">${esc(m.artifact_hash||'—')}</strong></div>`:`<div class="notice error">The production artifact could not be loaded. Check the ML service logs.</div>`}</div><div class="panel"><div class="panel-head"><h2>Baseline lifecycle</h2><span class="badge ${bs.state==='upgrading'?'medium':'benign'}">${esc(bs.state||'ready')}</span></div><p class="muted small">${esc(bs.message||'Production model loaded.')}</p>${m.training_scope==='verified-preview-fallback'?'<div class="notice warning">The packaged model is trained on a genuine but deliberately small verified CICIDS2017-derived preview so inference works even offline. The service automatically attempts to download and promote the stronger 20,000-row public baseline. This fallback is not presented as a full research-grade result.</div>':'<div class="notice">A stronger baseline is active. You can still retrain on the full official CICIDS2017 data for the final project evaluation.</div>'}${bs.last_error?`<div class="notice error" style="margin-top:12px">Last upgrade attempt: ${esc(bs.last_error)}</div>`:''}${canAdmin()?'<button class="btn" id="upgrade-active" style="margin-top:14px">Retry public baseline upgrade</button>':''}</div></div><div class="panel" style="margin-top:16px"><div class="panel-head"><h2>Feature contract</h2><span class="muted small">Exact fields expected by inference</span></div>${m.ready?`<div class="feature-list">${(m.feature_names||[]).map(x=>`<span class="feature-chip">${esc(x)}</span>`).join('')}</div><div class="quick-actions" style="margin-top:14px"><button class="btn small" id="model-load-single">Open Single Analysis</button><a class="btn ghost small" href="/test-data/single-benign.json" download>Download benign fixture</a><a class="btn ghost small" href="/test-data/single-portscan.json" download>Download PortScan fixture</a></div>`:empty('No feature contract','The model must be loaded before the schema is available.')}</div><div class="panel" style="margin-top:16px"><div class="panel-head"><h2>Research retraining</h2><span class="muted small">Optional — the app already works without this step</span></div>${canAdmin()?`<form id="train-form" class="settings-grid"><div><div class="field"><label>Dataset path visible to ML service</label><input class="input" name="dataset_path" value="/data/cicids2017" required></div></div><div><div class="field"><label>Optional row cap</label><input class="input" name="sample_limit" type="number" min="20"><span class="muted small">Leave blank for all cleaned rows.</span></div><button class="btn primary">Train and compare models</button></div></form>`:'<div class="notice">Only administrators can train or replace the production model.</div>'}</div>`;
  wireCopyButtons(document.getElementById('content'));
  document.getElementById('model-load-single')?.addEventListener('click',()=>go('analyze'));
  document.getElementById('upgrade-active')?.addEventListener('click',async e=>{const btn=e.currentTarget;btn.disabled=true;btn.textContent='Upgrade requested…';try{await api('/model/upgrade',{method:'POST',body:JSON.stringify({})});toast('Public baseline upgrade started.');setTimeout(()=>renderModel(),1800)}catch(err){toast(err.message,'error')}finally{btn.disabled=false;btn.textContent='Retry public baseline upgrade'}});
  if(canAdmin())document.getElementById('train-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));const payload={dataset_path:f.dataset_path};if(f.sample_limit)payload.sample_limit=Number(f.sample_limit);const btn=e.currentTarget.querySelector('button');btn.disabled=true;btn.textContent='Training CICIDS2017 data…';try{const r=await api('/model/train',{method:'POST',body:JSON.stringify(payload)});toast(`Model ${r.version} trained and activated.`);renderModel()}catch(err){toast(err.message,'error')}finally{btn.disabled=false;btn.textContent='Train and compare models'}};
}

/* ===== PSA SIMPLE MODE (v5) =====
   The advanced engine remains available, but the default interface teaches the
   submitted PSA first: traffic -> Node.js -> Python ML -> MongoDB -> alert.
*/
const SIMPLE_ADVANCED_ROUTES = new Set(['live','incidents','analytics','model','benchmark','testkit','readiness','integrations','users','audit','settings']);
let simpleAdvancedOpen = localStorage.getItem('sentinel_simple_advanced') === '1';

Object.assign(routeMeta, {
  onboarding:['Quick start','Learn the project by doing one simple analysis first.'],
  dashboard:['Overview','See what has been analyzed and whether suspicious traffic was detected.'],
  analyze:['Analyze Traffic','Test one network-flow record with the machine-learning model.'],
  batch:['Upload Traffic','Analyze many network-flow records from a CSV file.'],
  detections:['Results History','See every traffic analysis result stored by the system.'],
  alerts:['Security Alerts','Review suspicious operational traffic that needs attention.'],
  reports:['Reports','Download a simple PDF or CSV summary of stored security activity.'],
  help:['How It Works','Understand the whole project, what to upload, and which code files matter.'],
  live:['Live Monitoring','Watch traffic arrive automatically from a connected network-flow collector.'],
  incidents:['Incidents','Track serious alerts that were escalated for investigation.'],
  analytics:['Analytics','View deeper trends across stored detections.'],
  model:['AI Model','See the active machine-learning model and its evaluation information.'],
  benchmark:['Model Evaluation','Test the model against labelled CICIDS2017-derived traffic.'],
  testkit:['Test Tools','Run isolated technical test scenarios.'],
  readiness:['System Status','Check Node.js, MongoDB, Python ML and model availability.'],
  integrations:['Live Traffic Setup','Connect a compatible network-flow collector.'],
  users:['Organization & Team','Manage people who can access this organization workspace.'],
  audit:['Audit Log','Review important actions performed in this workspace.'],
  settings:['Settings','Configure alert and risk thresholds for this organization.']
});

function pageHead(route, actions=''){
  const [t,s]=routeMeta[route]||routeMeta.dashboard;
  const title=document.getElementById('top-title');if(title)title.textContent=t;
  const advanced=SIMPLE_ADVANCED_ROUTES.has(route);
  return `<div class="page-head"><div><div class="eyebrow">${esc(currentOrganization?.name||'ORGANIZATION')} · MABELI SENTINEL</div><h1>${esc(t)}</h1><p>${esc(s)}</p></div><div class="actions">${actions}</div></div>${advanced?'<div class="simple-advanced-note"><strong>Advanced tool</strong><span>You do not need this page to explain the core PSA. It extends the same traffic → AI → result workflow.</span></div>':''}`;
}

function shellHtml(){
  const advancedBlock=simpleAdvancedOpen?`<div class="nav-section">ADVANCED · OPTIONAL</div>${navButton('live','Live Monitoring','LM')}${navButton('incidents','Incidents','IN')}${navButton('analytics','Analytics','AN')}${navButton('model','AI Model','AI')}${navButton('benchmark','Model Evaluation','EV')}${navButton('readiness','System Status','ST')}${navButton('integrations','Live Traffic Setup','LS',true)}${navButton('users','Organization & Team','TM',true)}${navButton('audit','Audit Log','LG',true)}${navButton('settings','Settings','SE',true)}${navButton('testkit','Test Tools','TT')}`:'';
  return `<div class="shell"><aside class="sidebar" id="sidebar"><div class="side-brand"><div class="brand-mark"><div class="brand-glyph"><span>MS</span></div><div><strong>MABELI SENTINEL</strong><small>BY MABELI TECHNOLOGY</small></div></div></div><div class="workspace-box"><label>Company workspace</label><select class="select workspace-select" id="workspace-select">${organizations.map(o=>`<option value="${o._id}" ${String(o._id)===String(currentOrganization?._id)?'selected':''}>${esc(o.name)}</option>`).join('')}</select></div><nav class="nav"><div class="nav-section">CORE PROJECT</div>${navButton('dashboard','Overview','01')}${navButton('analyze','Analyze Traffic','02')}${navButton('batch','Upload Traffic','03')}${navButton('detections','Results History','04')}${navButton('alerts','Security Alerts','05')}${navButton('reports','Reports','06')}${navButton('help','How It Works','?')}<button type="button" id="advanced-toggle" class="advanced-toggle ${simpleAdvancedOpen?'open':''}"><span class="nav-icon">${simpleAdvancedOpen?'−':'+'}</span>${simpleAdvancedOpen?'Hide':'Show'} advanced tools</button>${advancedBlock}</nav><div class="sidebar-foot"><div class="user-chip"><div class="avatar">${esc((currentUser?.name||'U').slice(0,2).toUpperCase())}</div><div><strong>${esc(currentUser?.name)}</strong><span>${esc(currentUser?.role)} · ${esc(currentOrganization?.name||'')}</span></div></div><button class="btn ghost small full" id="logout">Sign out</button></div></aside><main class="main"><header class="topbar"><div class="topbar-left"><button class="btn ghost small mobile-menu" id="menu">MENU</button><div class="page-title" id="top-title"></div></div><div class="system-state" id="system-state"><span class="dot"></span>Checking system</div></header><section class="content" id="content"></section></main></div>`;
}

function renderShell(){
  if(SIMPLE_ADVANCED_ROUTES.has(currentRoute)) simpleAdvancedOpen=true;
  app.innerHTML=shellHtml();
  document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route));
  document.getElementById('logout').onclick=logout;
  document.getElementById('menu').onclick=()=>document.getElementById('sidebar').classList.toggle('open');
  const ws=document.getElementById('workspace-select');if(ws)ws.onchange=()=>switchWorkspace(ws.value);
  const adv=document.getElementById('advanced-toggle');if(adv)adv.onclick=()=>{simpleAdvancedOpen=!simpleAdvancedOpen;localStorage.setItem('sentinel_simple_advanced',simpleAdvancedOpen?'1':'0');renderShell()};
  connectSocket();checkHealth();renderRoute();
}

function simpleFlow(){return `<div class="simple-flow"><div><b>1</b><strong>Traffic</strong><span>Network-flow data enters the app</span></div><i>→</i><div><b>2</b><strong>Node.js</strong><span>Receives and validates it</span></div><i>→</i><div><b>3</b><strong>Python AI</strong><span>Predicts normal or malicious</span></div><i>→</i><div><b>4</b><strong>MongoDB</strong><span>Saves the result</span></div><i>→</i><div><b>5</b><strong>Alert</strong><span>Suspicious traffic is surfaced</span></div></div>`}

async function renderOnboarding(){
  const o=await api('/onboarding').catch(()=>({checklist:{}}));const c=o.checklist||{};
  document.getElementById('content').innerHTML=`${pageHead('onboarding')}<div class="simple-intro"><div><div class="eyebrow">START WITH YOUR ORGANIZATION</div><h2>Analyze your own traffic first. Practice data is there only when you want it.</h2><p>The core workflow is simple: provide network-flow data, let the Python model classify it, save the result in MongoDB, and surface suspicious operational traffic as an alert.</p></div><div class="hero-actions"><button class="btn primary" data-go="batch">Upload my traffic</button><button class="btn" data-go="analyze">Analyze one record</button></div></div>${simpleFlow()}<div class="simple-three"><article><b>STEP 1</b><h3>Provide traffic</h3><p>Upload a CSV of your organization's flow records or analyze one JSON flow record.</p><button class="btn small" data-go="batch">Upload organization CSV</button></article><article><b>STEP 2</b><h3>Review saved results</h3><p>Every AI decision is stored in MongoDB and appears in Results History.</p><button class="btn small" data-go="detections">Open Results History</button></article><article><b>STEP 3</b><h3>Review suspicious activity</h3><p>Operational malicious detections can create alerts when they cross your configured threshold.</p><button class="btn small" data-go="alerts">Open Security Alerts</button></article></div><div class="practice-strip"><div><span class="practice-kicker">OPTIONAL PRACTICE</span><strong>New to network-flow data?</strong><p>Use the built-in normal and suspicious samples to learn the workflow without adding them to your organization's operational records.</p></div><button class="btn ghost" data-go="analyze">Try a sample</button></div><div class="notice"><strong>For your defense:</strong> if you can explain Traffic → Node.js → Python AI → MongoDB → Alert, you understand the core PSA. Open <button class="inline-link" data-go="help">How It Works</button> for the exact source-code path.</div>`;
  document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
}

async function renderDashboard(){
  const [d,r]=await Promise.all([api('/dashboard?scope=operational'),api('/system/readiness').catch(()=>null)]);
  const total=d.total||0,mal=d.malicious||0;
  const gettingStarted=!total;
  document.getElementById('content').innerHTML=`${pageHead('dashboard','<button class="btn primary" data-go="batch">Upload traffic</button><button class="btn" data-go="analyze">Analyze one record</button>')}<div class="simple-intro compact"><div><div class="eyebrow">YOUR ORGANIZATION WORKSPACE</div><h2>${gettingStarted?'Ready to analyze real traffic.':'Your latest operational security picture.'}</h2><p>${gettingStarted?'Start by uploading a compatible network-flow CSV or analyzing one flow record. Practice samples are available separately if you simply want to learn how the system behaves.':'These numbers represent operational traffic stored for this organization. Practice and model-evaluation records are kept separate.'}</p></div><button class="btn ghost" data-go="help">How it works</button></div>${simpleFlow()}<div class="grid simple-stats"><div class="stat"><div class="label">Traffic analyzed</div><div class="value">${total.toLocaleString()}</div><small>Organization decisions</small></div><div class="stat"><div class="label">Normal</div><div class="value">${(d.benign||0).toLocaleString()}</div><small>Benign predictions</small></div><div class="stat"><div class="label">Suspicious</div><div class="value">${mal.toLocaleString()}</div><small>Malicious predictions</small></div><div class="stat critical"><div class="label">Active alerts</div><div class="value">${Number(d.activeAlerts||0).toLocaleString()}</div><small>Need attention</small></div></div>${gettingStarted?`<div class="start-grid"><article class="start-card primary-start"><span>RECOMMENDED</span><h3>Upload your organization's traffic</h3><p>Choose a compatible CSV. Sentinel validates it, shows progress, analyzes every row and opens the saved results.</p><button class="btn primary" data-go="batch">Upload traffic CSV</button></article><article class="start-card"><span>SINGLE RECORD</span><h3>Analyze one flow</h3><p>Use a JSON network-flow record when you want to inspect one connection at a time.</p><button class="btn" data-go="analyze">Analyze one record</button></article><article class="start-card practice"><span>OPTIONAL PRACTICE</span><h3>See it work with sample data</h3><p>Run genuine CICIDS2017-derived samples without treating them as attacks against your organization.</p><button class="btn ghost" data-go="analyze">Try practice samples</button></article></div>`:''}<div class="panel-grid" style="margin-top:16px"><div class="panel"><div class="panel-head"><h2>Recent organization results</h2><button class="btn ghost small" data-go="detections">View all</button></div>${d.recentDetections?.length?simpleDetectionTable(d.recentDetections):`<div class="simple-empty"><strong>No organization traffic has been analyzed yet</strong><span>The platform is ready. Upload your own CSV or analyze a single flow to create the first operational result.</span><div class="row-actions"><button class="btn primary" data-go="batch">Upload my traffic</button><button class="btn" data-go="analyze">Analyze one record</button><button class="btn ghost" data-go="analyze">Optional: try sample</button></div></div>`}</div><div class="panel"><div class="panel-head"><h2>Core services</h2></div><div class="simple-status"><div><span class="status-dot ${r?.services?.api?'ok':''}"></span><strong>Node.js API</strong><small>${r?.services?.api?'Online':'Unavailable'}</small></div><div><span class="status-dot ${r?.services?.database?'ok':''}"></span><strong>MongoDB</strong><small>${r?.services?.database?'Connected':'Unavailable'}</small></div><div><span class="status-dot ${r?.services?.ml?'ok':''}"></span><strong>Python AI</strong><small>${r?.model?.ready?'Model ready':'Check ML service'}</small></div></div>${canAdmin()?'<button class="btn ghost small status-link" data-go="readiness">Technical system status</button>':''}</div></div>`;
  document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));wireSimpleDetectionRows();
}

function simpleDetectionTable(items){return `<div class="table-wrap"><table class="table simple-table"><thead><tr><th>Time</th><th>Result</th><th>Detected type</th><th>Confidence</th><th>Risk</th><th></th></tr></thead><tbody>${items.map(r=>`<tr data-simple-detection="${r._id}"><td>${esc(fmtDate(r.createdAt))}</td><td>${r.prediction==='malicious'?'<span class="badge malicious">Suspicious</span>':'<span class="badge benign">Normal</span>'}</td><td>${esc(r.attackType||'—')}</td><td>${pct(r.confidence)}</td><td>${Number(r.riskScore||0)}/100</td><td><button class="btn ghost small" data-open-simple="${r._id}">View</button></td></tr>`).join('')}</tbody></table></div>`}
function wireSimpleDetectionRows(){document.querySelectorAll('[data-simple-detection]').forEach(r=>r.onclick=e=>{if(e.target.closest('button'))return;openDetection(r.dataset.simpleDetection)});document.querySelectorAll('[data-open-simple]').forEach(b=>b.onclick=e=>{e.stopPropagation();openDetection(b.dataset.openSimple)})}

function friendlyAnalysisResult(r,practice=false){const d=r.detection;const bad=d.prediction==='malicious';return `<div class="friendly-result ${bad?'danger':'safe'}"><div class="result-symbol">${bad?'!':'✓'}</div><div><div class="eyebrow">ANALYSIS RESULT${practice?' · PRACTICE SAMPLE':''}</div><h2>${bad?'Suspicious traffic detected':'Traffic appears normal'}</h2><p>${bad?`The model found a pattern most similar to <strong>${esc(d.attackType||'malicious traffic')}</strong>.`:'The model did not identify a supported malicious pattern in this flow.'}</p><div class="friendly-metrics"><span><small>Prediction</small><strong>${bad?'Malicious':'Benign'}</strong></span><span><small>Confidence</small><strong>${pct(d.confidence)}</strong></span><span><small>Risk</small><strong>${Number(d.riskScore||0)}/100</strong></span></div>${practice?'<div class="notice">This was a practice record. It does not mean your organization was attacked.</div>':r.alert?`<div class="notice error">A security alert was created because this operational traffic crossed the alert threshold.</div>`:'<div class="notice">The result was stored in Detection History.</div>'}<div class="row-actions"><button class="btn small" data-result-id="${d._id}">View saved result</button></div></div></div>`}

async function renderAnalyze(){
  const m=await api('/model');
  const ready=Boolean(m.ready!==false);
  document.getElementById('content').innerHTML=`${pageHead('analyze')}<div class="simple-intro compact"><div><div class="eyebrow">ANALYZE ONE NETWORK FLOW</div><h2>Use your organization's traffic by default.</h2><p>Paste or upload one JSON network-flow record. Sentinel sends it through the real Node.js → Python ML → MongoDB pipeline. Practice samples are available separately on the right.</p></div></div><div class="analysis-layout"><div class="panel main-analysis-panel"><div class="panel-head"><div><h2>Analyze one traffic record</h2><span class="muted small">${ready?`${Number(m.feature_count||0)} model features available`:'Model unavailable'}</span></div></div>${ready?`<form id="simple-manual-form"><div class="field"><label>Load JSON file <span class="optional-label">optional</span></label><input class="input" id="single-json-file" type="file" accept=".json,application/json"><span class="muted small">Choose a JSON flow file, or paste the values below.</span></div><div class="field"><div class="field-label-row"><label>Traffic features (JSON)</label><div class="mini-actions"><a class="inline-link" href="/test-data/single-benign.json" download>Download example format</a><button type="button" class="inline-link" id="show-feature-help">Expected fields</button></div></div><textarea class="textarea json-box" id="feature-json" required placeholder='{"Destination Port":443,"Flow Duration":523091,...}'></textarea></div><div class="settings-grid compact-settings"><div class="field"><label>Record as</label><select class="select" id="single-environment"><option value="operational" selected>Organization traffic — real operational record</option><option value="test">Practice/test record — kept separate</option></select></div><div class="field"><label>Source name</label><input class="input" id="single-source-name" value="Analyst single-flow input" placeholder="e.g. Office gateway capture"></div></div><div id="single-mode-note" class="notice warning">Organization mode can create a real workspace alert if this traffic is classified as suspicious above your threshold.</div><button type="submit" class="btn primary">Analyze traffic</button></form><div id="feature-help" class="notice" style="display:none;margin-top:12px">The model expects numeric network-flow measurements such as Destination Port, Flow Duration, packet counts and packet lengths. A flow collector normally generates these values. Use the downloadable JSON as a format reference; Advanced → AI Model shows the full active schema.</div>`:`<div class="notice error">The machine-learning model is not ready. Open Advanced → System Status to check the Python ML service and active model.</div>`}<div id="analysis-result" style="margin-top:16px"></div></div><aside class="panel practice-panel"><div class="practice-kicker">OPTIONAL PRACTICE</div><h2>Not ready with your own data?</h2><p>These samples are genuine CICIDS2017-derived records. They always stay in the separate Practice environment and never represent an attack against your organization.</p><div class="practice-sample-list"><article><div class="sample-type normal">NORMAL</div><div><strong>Benign traffic</strong><span>See how a normal prediction looks.</span></div><button class="btn small" data-run-fixture="/test-data/single-benign.json">Run sample</button></article><article><div class="sample-type threat">SUSPICIOUS</div><div><strong>Port Scan traffic</strong><span>See how a malicious prediction looks.</span></div><button class="btn small" data-run-fixture="/test-data/single-portscan.json">Run sample</button></article></div><p class="muted small practice-note">Practice results are stored separately and can be viewed under Results History → Practice.</p></aside></div>`;
  const resultEl=document.getElementById('analysis-result');
  document.querySelectorAll('[data-run-fixture]').forEach(b=>b.onclick=async()=>{const old=b.textContent;b.disabled=true;b.textContent='Analyzing…';try{const data=await fetch(b.dataset.runFixture,{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('Practice fixture is unavailable.');return r.json()});const r=await api('/analysis/single',{method:'POST',body:JSON.stringify({features:data.features||data,meta:{environment:'test',sourceName:`Practice sample · ${data.label||'traffic'}`}})});resultEl.innerHTML=friendlyAnalysisResult(r,true);resultEl.scrollIntoView({behavior:'smooth',block:'nearest'});document.querySelector('[data-result-id]')?.addEventListener('click',()=>openDetection(r.detection._id));toast('Practice sample analyzed successfully.')}catch(e){resultEl.innerHTML=`<div class="notice error"><strong>Practice analysis failed.</strong><br>${esc(e.message)}</div>`;toast(e.message,'error')}finally{b.disabled=false;b.textContent=old}});
  if(!ready)return;
  const fileInput=document.getElementById('single-json-file');
  fileInput.onchange=async()=>{const file=fileInput.files?.[0];if(!file)return;try{const text=await file.text();const parsed=JSON.parse(text);const features=parsed.features||parsed;if(!features||Array.isArray(features)||typeof features!=='object')throw new Error('The JSON file must contain an object of traffic features.');document.getElementById('feature-json').value=JSON.stringify(features,null,2);if(parsed.sourceName)document.getElementById('single-source-name').value=parsed.sourceName;toast(`${file.name} loaded.`)}catch(err){fileInput.value='';toast(`Could not load JSON: ${err.message}`,'error')}};
  document.getElementById('show-feature-help').onclick=()=>{const el=document.getElementById('feature-help');el.style.display=el.style.display==='none'?'block':'none'};
  document.getElementById('single-environment').onchange=e=>{const practice=e.target.value==='test';const note=document.getElementById('single-mode-note');note.className=`notice ${practice?'':'warning'}`;note.textContent=practice?'Practice mode keeps this result separate from your organization dashboard and real alerts.':'Organization mode can create a real workspace alert if this traffic is classified as suspicious above your threshold.';document.getElementById('single-source-name').value=practice?'Custom practice flow':'Analyst single-flow input'};
  document.getElementById('simple-manual-form').onsubmit=async e=>{e.preventDefault();let features;try{features=JSON.parse(document.getElementById('feature-json').value);if(!features||Array.isArray(features)||typeof features!=='object')throw new Error()}catch{return toast('Paste or load a valid JSON object of network-flow features.','error')}const environment=document.getElementById('single-environment').value;const btn=submitButton(e.currentTarget),old=btn.textContent;btn.disabled=true;btn.textContent='Analyzing traffic…';resultEl.innerHTML='<div class="analysis-progress"><div class="activity-spinner"></div><div><div class="eyebrow">ANALYSIS IN PROGRESS</div><h3>Running the machine-learning model</h3><p>Node.js is sending this flow to the Python model. The prediction will then be stored in MongoDB.</p></div></div>';try{const r=await api('/analysis/single',{method:'POST',body:JSON.stringify({features,meta:{environment,sourceName:document.getElementById('single-source-name').value||'Analyst single-flow input'}})});resultEl.innerHTML=friendlyAnalysisResult(r,environment==='test');document.querySelector('[data-result-id]')?.addEventListener('click',()=>openDetection(r.detection._id));resultEl.scrollIntoView({behavior:'smooth',block:'nearest'});detectionEnvironment=environment;toast('Traffic analysis completed.')}catch(err){resultEl.innerHTML=`<div class="friendly-batch failed"><div class="result-symbol">!</div><div><div class="eyebrow">ANALYSIS FAILED</div><h3>The traffic record was not processed</h3><p>${esc(err.message)}</p><div class="notice">Try the downloadable example format, then compare its field names with your own data.</div></div></div>`;toast(err.message,'error')}finally{btn.disabled=false;btn.textContent=old}};
}

async function renderBatch(){
  const model=await api('/model').catch(()=>({feature_names:[],feature_count:0}));
  const featureNames=model.feature_names||[];
  document.getElementById('content').innerHTML=`${pageHead('batch')}<div class="simple-intro compact"><div><div class="eyebrow">UPLOAD YOUR ORGANIZATION TRAFFIC</div><h2>Choose a CSV and Sentinel will analyze every selected row.</h2><p>Organization traffic is the default. Practice mode is optional and clearly separated so test records never look like real incidents.</p></div></div><div class="panel"><div class="upload-explainer"><div><b>1</b><strong>Choose CSV</strong><span>Sentinel checks the file</span></div><i>→</i><div><b>2</b><strong>Analyze</strong><span>Node.js sends rows to Python AI</span></div><i>→</i><div><b>3</b><strong>Review</strong><span>MongoDB stores each decision</span></div></div><form id="batch-form" enctype="multipart/form-data"><div class="data-mode-selector"><label class="data-mode-card selected" data-mode-card="operational"><input type="radio" name="modeChoice" value="operational" checked><span class="mode-mark">ORG</span><div><strong>Organization traffic</strong><small>Use for your own real/approved network-flow CSV. Suspicious results may create workspace alerts.</small></div></label><label class="data-mode-card" data-mode-card="test"><input type="radio" name="modeChoice" value="test"><span class="mode-mark">TEST</span><div><strong>Practice / test data</strong><small>Use when learning or testing. Results stay separate from your organization dashboard and real alerts.</small></div></label></div><input type="hidden" name="environment" id="batch-env" value="operational"><div class="field"><div class="field-label-row"><label>Traffic CSV file</label><div class="mini-actions"><a class="inline-link" href="/test-data/batch-unlabelled.csv" download>Download example format</a></div></div><input class="input" id="batch-file" name="file" type="file" accept=".csv,text/csv" required><span class="muted small">CSV rows should contain numeric network-flow fields. The selected file is checked before the Analyze button becomes available.</span></div><div id="batch-file-status" class="file-readiness"><div class="file-readiness-icon">CSV</div><div><strong>No file selected</strong><span>Choose your traffic CSV to inspect its name, size, row count and model-column match.</span></div></div><details class="batch-options"><summary>Processing options</summary><div class="field"><label>Maximum rows for this run</label><select class="select" name="maxRows"><option value="100">100 rows — quickest</option><option value="500" selected>500 rows — recommended</option><option value="1000">1,000 rows</option><option value="5000">5,000 rows — may take longer</option></select><span class="muted small">For a presentation, 100 or 500 rows gives visible results faster.</span></div></details><div class="form-actions"><button type="submit" class="btn primary" id="batch-submit" disabled>Choose a CSV first</button><button type="button" class="btn ghost" id="run-example-batch">Optional: run built-in example as practice</button></div></form><div id="batch-result" style="margin-top:16px"></div></div>`;
  const fileInput=document.getElementById('batch-file'),fileStatus=document.getElementById('batch-file-status'),submit=document.getElementById('batch-submit'),resultEl=document.getElementById('batch-result'),envInput=document.getElementById('batch-env');
  document.querySelectorAll('input[name="modeChoice"]').forEach(r=>r.onchange=()=>{envInput.value=r.value;document.querySelectorAll('[data-mode-card]').forEach(c=>c.classList.toggle('selected',c.dataset.modeCard===r.value));if(r.value==='test')toast('Practice mode selected. These results stay separate from organization alerts.')});
  fileInput.onchange=async()=>{
    const file=fileInput.files?.[0];submit.disabled=true;submit.textContent='Checking CSV…';
    if(!file){fileStatus.className='file-readiness';fileStatus.innerHTML='<div class="file-readiness-icon">CSV</div><div><strong>No file selected</strong><span>Choose a CSV before starting analysis.</span></div>';submit.textContent='Choose a CSV first';return}
    try{const info=await inspectCsvFile(file,featureNames);const looksCsv=/\.csv$/i.test(file.name)||String(file.type).includes('csv');if(!looksCsv)throw new Error('Please choose a .csv file.');if(info.headers.length<2)throw new Error('The file does not appear to contain a valid CSV header row.');const expected=Number(model.feature_count||featureNames.length||0);const matchText=expected?`${info.matched.length} of ${expected} active model fields matched by name`:`${info.headers.length} columns detected`;const rowText=info.rows===null?'Row count will be confirmed by the server':`${info.rows.toLocaleString()} data row${info.rows===1?'':'s'} detected`;fileStatus.className=`file-readiness ready ${info.matched.length===0&&expected?'warning':''}`;fileStatus.innerHTML=`<div class="file-readiness-icon">${info.matched.length||!expected?'✓':'!'}</div><div><strong>${esc(file.name)}</strong><span>${fileSizeLabel(file.size)} · ${rowText}</span><small>${esc(matchText)}.${info.matched.length===0&&expected?' The server can impute missing fields, but use the example format if this is unexpected.':' Ready for analysis.'}</small></div>`;submit.disabled=false;submit.textContent='Analyze CSV now'}catch(err){fileStatus.className='file-readiness error';fileStatus.innerHTML=`<div class="file-readiness-icon">!</div><div><strong>File needs attention</strong><span>${esc(err.message)}</span></div>`;submit.disabled=true;submit.textContent='Fix the CSV first'}
  };
  const performBatch=async({formData,fileName,environment,button})=>{
    const old=button?.textContent||'Analyze CSV';if(button){button.disabled=true;button.textContent='Analyzing…'}const started=Date.now();
    resultEl.innerHTML=`<div class="analysis-progress"><div class="activity-spinner" aria-hidden="true"></div><div><div class="eyebrow">ANALYSIS IN PROGRESS</div><h3>Processing ${esc(fileName)}</h3><p>Node.js is reading the CSV. Each row is passed through the Python machine-learning model and the resulting detection is saved to MongoDB.</p><div class="progress-pulse"><span></span></div><small id="batch-elapsed">Working… 0 seconds</small><div class="notice" style="margin-top:12px">Keep this page open. The operation is real, so larger batches take longer than a static demonstration.</div></div></div>`;resultEl.scrollIntoView({behavior:'smooth',block:'nearest'});toast('CSV accepted. Analysis has started.');
    const timer=setInterval(()=>{const el=document.getElementById('batch-elapsed');if(el)el.textContent=`Working… ${Math.floor((Date.now()-started)/1000)} seconds`},1000);
    try{const data=await api('/analysis/batch',{method:'POST',body:formData});const rows=Array.isArray(data.results)?data.results:[];const good=rows.filter(x=>!x.error),bad=good.filter(x=>x.prediction==='malicious').length,errors=rows.length-good.length,normal=Math.max(0,good.length-bad);const summary={fileName,processed:Number(data.processed||rows.length||0),normal,suspicious:bad,errors,environment:data.environment||environment,seconds:Math.max(1,Math.round((Date.now()-started)/1000)),createdAt:Date.now()};if(!good.length&&errors){const examples=rows.filter(x=>x.error).slice(0,3).map(x=>`<li>${esc(x.error)}</li>`).join('');resultEl.innerHTML=`<div class="friendly-batch failed"><div class="result-symbol">!</div><div><div class="eyebrow">ANALYSIS FINISHED WITH ERRORS</div><h3>No rows produced a usable detection</h3><p>The CSV reached the backend, but the model could not process the supplied rows.</p><ul>${examples}</ul><div class="row-actions"><a class="btn" href="/test-data/batch-unlabelled.csv" download>Download known-good format</a><button class="btn ghost" type="button" data-go-help>Open upload help</button></div></div></div>`;document.querySelector('[data-go-help]')?.addEventListener('click',()=>go('help'));toast('The CSV was read, but its rows could not be analyzed.','error');return}sessionStorage.setItem('sentinel_last_batch_summary',JSON.stringify(summary));detectionEnvironment=summary.environment==='operational'?'operational':'test';resultEl.innerHTML=`<div class="friendly-batch complete"><div class="result-symbol">✓</div><div><div class="eyebrow">BATCH ANALYSIS COMPLETE</div><h3>${summary.processed.toLocaleString()} traffic rows processed</h3><div class="friendly-metrics"><span><small>Normal</small><strong>${normal.toLocaleString()}</strong></span><span><small>Suspicious</small><strong>${bad.toLocaleString()}</strong></span><span><small>Errors</small><strong>${errors.toLocaleString()}</strong></span><span><small>Time</small><strong>${summary.seconds}s</strong></span></div><p>${summary.environment==='operational'?'These are organization results. Any qualifying malicious rows can create operational alerts.':'These are practice results and stay separate from organization alerts.'}</p><div class="form-actions"><button type="button" class="btn primary" id="open-batch-results-now">View saved results</button><button type="button" class="btn" id="stay-batch">Stay on this page</button></div></div></div>`;document.getElementById('open-batch-results-now').onclick=()=>go('detections');const redirectTimer=setTimeout(()=>{if(currentRoute==='batch')go('detections')},1800);document.getElementById('stay-batch').onclick=()=>{clearTimeout(redirectTimer);toast('Staying on Upload Traffic. Your results are already saved.')};toast(`Analysis complete: ${summary.processed} rows processed. Opening Results History…`);return summary}catch(err){resultEl.innerHTML=`<div class="friendly-batch failed"><div class="result-symbol">!</div><div><div class="eyebrow">ANALYSIS FAILED</div><h3>The CSV was not processed</h3><p>${esc(err.message)}</p><div class="notice">Try the included example as Practice. If it works, compare its column names with your own file.</div></div></div>`;toast(`CSV analysis failed: ${err.message}`,'error')}finally{clearInterval(timer);if(button){button.disabled=false;button.textContent=old}}
  };
  document.getElementById('batch-form').onsubmit=async e=>{e.preventDefault();const file=fileInput.files?.[0];if(!file)return toast('Choose a CSV file first.','error');const fd=new FormData(e.currentTarget);fd.delete('modeChoice');fd.set('environment',envInput.value);await performBatch({formData:fd,fileName:file.name,environment:envInput.value,button:submit})};
  document.getElementById('run-example-batch').onclick=async e=>{const btn=e.currentTarget;try{const response=await fetch('/test-data/batch-unlabelled.csv',{cache:'no-store'});if(!response.ok)throw new Error('Built-in example CSV is unavailable.');const blob=await response.blob();const fd=new FormData();fd.append('file',blob,'mabeli-practice-traffic.csv');fd.append('environment','test');fd.append('maxRows','100');document.querySelector('input[name="modeChoice"][value="test"]').checked=true;envInput.value='test';document.querySelectorAll('[data-mode-card]').forEach(c=>c.classList.toggle('selected',c.dataset.modeCard==='test'));await performBatch({formData:fd,fileName:'mabeli-practice-traffic.csv',environment:'test',button:btn})}catch(err){toast(err.message,'error')}};
}

async function renderDetections(page=1){
  const envLabel=detectionEnvironment||'operational';const q=new URLSearchParams({page:String(page),limit:'25'});if(envLabel!=='all')q.set('environment',envLabel);const d=await api(`/detections?${q}`);
  let batchBanner='';try{const last=JSON.parse(sessionStorage.getItem('sentinel_last_batch_summary')||'null');if(last&&Date.now()-Number(last.createdAt||0)<10*60*1000){batchBanner=`<div class="batch-success-banner" id="batch-success-banner"><div class="batch-success-mark">✓</div><div><strong>CSV analysis completed successfully</strong><span>${esc(last.fileName||'CSV')} · ${Number(last.processed||0).toLocaleString()} processed · ${Number(last.normal||0).toLocaleString()} normal · ${Number(last.suspicious||0).toLocaleString()} suspicious · ${Number(last.errors||0).toLocaleString()} errors</span><small>${last.environment==='operational'?'Organization results are shown below.':'Practice results are shown below and stay separate from real alerts.'}</small></div><button type="button" class="btn ghost small" id="dismiss-batch-summary">Dismiss</button></div>`}}catch{}
  document.getElementById('content').innerHTML=`${pageHead('detections')}${batchBanner}<div class="result-scope-bar"><div><strong>Which results do you want to see?</strong><span>Organization is the normal working view. Practice is optional test data.</span></div><div class="simple-filter"><button data-denv="operational" class="${envLabel==='operational'?'active':''}">Organization</button><button data-denv="test" class="${envLabel==='test'?'active':''}">Practice</button>${simpleAdvancedOpen?`<button data-denv="benchmark" class="${envLabel==='benchmark'?'active':''}">Model evaluation</button><button data-denv="all" class="${envLabel==='all'?'active':''}">All</button>`:''}</div></div><div class="panel">${d.items.length?simpleDetectionTable(d.items):`<div class="simple-empty"><strong>No ${envLabel==='test'?'practice':'organization'} results yet</strong><span>${envLabel==='test'?'Practice data is optional. Run a sample from Analyze Traffic when you want to test the workflow.':'Upload your traffic CSV or analyze one network-flow record to create an operational result.'}</span><div class="row-actions"><button class="btn primary" data-go="${envLabel==='test'?'analyze':'batch'}">${envLabel==='test'?'Try practice sample':'Upload organization traffic'}</button><button class="btn" data-go="analyze">Analyze one record</button></div></div>`}<div class="pager"><button class="btn small" ${d.page<=1?'disabled':''} id="prev">Previous</button><span class="muted small">Page ${d.page} of ${d.pages}</span><button class="btn small" ${d.page>=d.pages?'disabled':''} id="next">Next</button></div></div>`;
  document.getElementById('dismiss-batch-summary')?.addEventListener('click',()=>{sessionStorage.removeItem('sentinel_last_batch_summary');document.getElementById('batch-success-banner')?.remove()});
  document.querySelectorAll('[data-denv]').forEach(b=>b.onclick=()=>{detectionEnvironment=b.dataset.denv;renderDetections(1)});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.getElementById('prev').onclick=()=>renderDetections(d.page-1);document.getElementById('next').onclick=()=>renderDetections(d.page+1);wireSimpleDetectionRows();
}

async function renderHelp(){
  const m=await api('/model').catch(()=>({}));
  document.getElementById('content').innerHTML=`${pageHead('help')}<div class="simple-intro"><div><div class="eyebrow">YOUR ENTIRE PSA</div><h2>Mabeli Sentinel checks network traffic with AI and alerts the user when suspicious traffic is found.</h2><p>Do not try to memorize every advanced page. The core project is the five-step flow below.</p></div><button class="btn primary" data-go="analyze">Try it now</button></div>${simpleFlow()}<div class="simple-three"><article><b>INPUT</b><h3>What do I provide?</h3><p>Network-flow measurements. For learning, use the built-in samples or example CSV. In live use, a flow collector produces these values automatically.</p><div class="row-actions"><a class="btn ghost small" href="/test-data/single-benign.json" download>JSON example</a><a class="btn ghost small" href="/test-data/batch-unlabelled.csv" download>CSV example</a></div></article><article><b>OUTPUT</b><h3>What does the AI return?</h3><p>Benign or malicious, likely attack type, prediction confidence and a risk score.</p></article><article><b>STORAGE</b><h3>What does MongoDB save?</h3><p>The original traffic event, the AI detection, and an alert when applicable.</p></article></div><div class="panel" style="margin-top:16px"><div class="panel-head"><h2>If a lecturer says “show me the code”</h2><span class="muted small">Open these files in this order</span></div><div class="code-map"><div><b>1</b><strong>backend/src/server.js</strong><span>Starts Node.js and Express.</span></div><div><b>2</b><strong>backend/src/routes/api.js</strong><span>Receives Analyze Traffic and Upload Traffic requests.</span></div><div><b>3</b><strong>backend/src/services/detection.js</strong><span>Core workflow: save traffic → call AI → save result → create alert.</span></div><div><b>4</b><strong>backend/src/services/ml.js</strong><span>Node.js sends the network features to Python.</span></div><div><b>5</b><strong>ml-service/app/main.py</strong><span>Loads the trained model and performs the prediction.</span></div><div><b>6</b><strong>backend/src/models/index.js</strong><span>MongoDB schemas for traffic, detections, alerts and users.</span></div><div><b>7</b><strong>frontend/public/app.js</strong><span>The pages and buttons you are using now.</span></div></div></div><div class="panel-grid" style="margin-top:16px"><div class="panel"><h2>Words you should know</h2><div class="help-list"><div><strong>Benign</strong><span>Traffic the model considers normal.</span></div><div><strong>Malicious</strong><span>Traffic that resembles a supported attack pattern.</span></div><div><strong>Detection</strong><span>One AI decision about one network flow.</span></div><div><strong>Alert</strong><span>A suspicious operational detection that needs attention.</span></div><div><strong>Confidence</strong><span>How strongly the model supports its prediction; it is not a guarantee.</span></div></div></div><div class="panel"><h2>Technology roles</h2><div class="help-list"><div><strong>Node.js + Express</strong><span>Main application backend and API.</span></div><div><strong>Python + scikit-learn</strong><span>Machine-learning prediction service.</span></div><div><strong>MongoDB</strong><span>Stores users, traffic, detections and alerts.</span></div><div><strong>CICIDS2017</strong><span>Labelled intrusion-detection data used to train/evaluate the model.</span></div><div><strong>Current model</strong><span>${esc(m.algorithm||'Loaded ML model')} · ${Number(m.feature_count||0)} features.</span></div></div></div></div><div class="notice" style="margin-top:16px"><strong>Core vs advanced:</strong> Overview, Analyze Traffic, Upload Traffic, Results History, Alerts and Reports are enough to explain the PSA. Live Monitoring, Incidents, Model Evaluation, Audit Logs and similar pages are optional extensions.</div>`;
  document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
}

async function renderAlerts(){
  const d=await api('/alerts?limit=50&environment=operational');
  document.getElementById('content').innerHTML=`${pageHead('alerts')}<div class="simple-intro compact"><div><div class="eyebrow">WHEN DOES AN ALERT APPEAR?</div><h2>Only suspicious organization traffic creates real security alerts.</h2><p>A normal prediction is simply stored. A malicious operational prediction that crosses your threshold can become an alert for someone to review.</p></div>${canAdmin()?'<button class="btn ghost" data-go="settings">Alert settings</button>':''}</div><div class="panel"><div class="panel-head"><h2>Current alerts</h2><span class="muted small">${Number(d.total||d.items?.length||0).toLocaleString()} stored</span></div>${d.items?.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Alert</th><th>Severity</th><th>Status</th><th>Last seen</th><th></th></tr></thead><tbody>${d.items.map(a=>`<tr data-simple-alert="${a._id}"><td><strong>${esc(a.title)}</strong><br><span class="muted small">${esc(a.detection?.attackType||'Suspicious traffic')}</span></td><td>${severityBadge(a.severity)}</td><td>${severityBadge(a.status)}</td><td>${fmtDate(a.lastSeenAt)}</td><td><button class="btn ghost small" data-open-alert="${a._id}">Review</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="simple-empty"><strong>No organization alerts right now</strong><span>This is not an error. Alerts appear only after real organization traffic is marked malicious and passes the configured alert threshold.</span><div class="row-actions"><button class="btn primary" data-go="analyze">Analyze traffic</button>${simpleAdvancedOpen?'<button class="btn" data-go="testkit">Practice alert workflow</button>':''}</div></div>`}</div>`;
  document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
  document.querySelectorAll('[data-simple-alert]').forEach(r=>r.onclick=e=>{if(e.target.closest('button'))return;const a=d.items.find(x=>x._id===r.dataset.simpleAlert);if(a)openAlert(a)});
  document.querySelectorAll('[data-open-alert]').forEach(b=>b.onclick=e=>{e.stopPropagation();const a=d.items.find(x=>x._id===b.dataset.openAlert);if(a)openAlert(a)});
}

async function renderReports(){
  const dashboard=await api('/dashboard?scope=operational').catch(()=>({total:0,malicious:0,activeAlerts:0}));
  document.getElementById('content').innerHTML=`${pageHead('reports')}<div class="simple-intro compact"><div><div class="eyebrow">TURN STORED RESULTS INTO A REPORT</div><h2>Export your organization's real security activity.</h2><p>Reports use operational data by default. Practice and model-evaluation exports remain optional under Advanced report options.</p></div></div><div class="report-readiness"><div><span>Organization detections</span><strong>${Number(dashboard.total||0).toLocaleString()}</strong></div><div><span>Suspicious</span><strong>${Number(dashboard.malicious||0).toLocaleString()}</strong></div><div><span>Active alerts</span><strong>${Number(dashboard.activeAlerts||0).toLocaleString()}</strong></div></div><div class="simple-three"><article><b>PDF</b><h3>Security summary</h3><p>A readable 30-day report for management, presentation or project defense.</p><button class="btn primary" id="simple-pdf">Download organization PDF</button></article><article><b>CSV</b><h3>Detection records</h3><p>Export the underlying organization detection records for spreadsheet review.</p><button class="btn" id="simple-csv">Download organization CSV</button></article><article><b>NEED DATA?</b><h3>${Number(dashboard.total||0)?'Analyze more traffic':'No organization data yet'}</h3><p>${Number(dashboard.total||0)?'Reports update automatically as more operational traffic is analyzed.':'Upload traffic first; the reports are generated from saved detections rather than placeholder content.'}</p><button class="btn" data-go="batch">Upload traffic</button></article></div><div id="report-feedback" style="margin-top:14px"></div><details class="advanced-input"><summary>Advanced report options — practice / evaluation data</summary><div class="panel details-panel"><div class="settings-grid"><div class="field"><label>Data source</label><select class="select" id="report-scope"><option value="operational">Organization traffic</option><option value="test">Practice data</option><option value="benchmark">Model evaluation data</option><option value="all">All stored data</option></select></div><div class="field"><label>Time period</label><select class="select" id="report-days"><option value="7">7 days</option><option value="30" selected>30 days</option><option value="90">90 days</option><option value="365">365 days</option></select></div></div><div class="form-actions"><button class="btn" id="advanced-pdf">Download selected PDF</button><button class="btn ghost" id="advanced-csv">Download selected CSV</button></div></div></details>`;
  const runDownload=async(button,ext,scope='operational',days='30')=>{const old=button.textContent;button.disabled=true;button.textContent='Preparing download…';const feedback=document.getElementById('report-feedback');feedback.innerHTML='<div class="analysis-progress compact-progress"><div class="activity-spinner"></div><div><strong>Generating report</strong><p>Sentinel is reading the selected MongoDB records and preparing your file.</p></div></div>';const ok=await downloadReport(`/reports/security.${ext}?days=${days}&scope=${scope}`,ext==='pdf'?'mabeli-security-report.pdf':'mabeli-detections.csv');feedback.innerHTML=ok?'<div class="notice"><strong>Report ready.</strong> Your browser download has started.</div>':'<div class="notice error"><strong>Report download failed.</strong> Check the message above and try again.</div>';button.disabled=false;button.textContent=old};
  document.getElementById('simple-pdf').onclick=e=>runDownload(e.currentTarget,'pdf');document.getElementById('simple-csv').onclick=e=>runDownload(e.currentTarget,'csv');
  document.getElementById('advanced-pdf').onclick=e=>runDownload(e.currentTarget,'pdf',document.getElementById('report-scope').value,document.getElementById('report-days').value);document.getElementById('advanced-csv').onclick=e=>runDownload(e.currentTarget,'csv',document.getElementById('report-scope').value,document.getElementById('report-days').value);
  document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
}



